$('date').textContent=E.date(s);$('season').textContent=E.season(s)+' · '+f.weather+((s.cycle||1)>1?' · '+s.cycle+'周目':'')+(s.mode==='century'?' · 100年商店街':'');$('cash').textContent=money(s.cash);$('cash').className=s.cash<0?'negative':'';$('debt').textContent=debt?'借入残高 '+money(debt):'借入なし';
