 if(V.alerts(s).length)$('forecast').innerHTML='<div class="notice warning"><b>'+esc(V.alerts(s)[0].title)+'</b><p>'+esc(V.alerts(s)[0].text)+'</p><button data-global="eventBrief">今月の注意と被害を確認</button></div>'+$('forecast').innerHTML;
