function confirmUpgrade(id){const b=s.buildings.find(v=>v.id===id),cost=E.upgradeCost(b,s),f=E.F(b.type);dialog(content(f.name+'を改装',`<p>改装費 ${money(cost)}。当月は工事で休業し、来月Lv.${b.level+1}として営業します。</p><p>魅力・受入能力・客単価が上がり、固定維持費は標準の${Math.round((1+b.level*C.balance.levelFixed)*100)}%になります。</p><p>今月の工事取消は返金されません。</p>`,`<div class="actions">${action('改装を始める','yes','primary')}${action('戻る','back')}</div>`),{yes:()=>run(()=>E.upgrade(s,id)),back:()=>detail(id)});}
