function campaign(id){const p=C.projects[id];if(!p||!P.projectVisible(s,id))return;const check=P.conditions(s,id),preview=E.projectPreview(s,id),{cost,reserved}=preview,f=preview.before,after=preview.after,net=preview.net,canReserve=check.ok&&!s.project&&E.canAct(s);
 const requirements=check.requirements.length?'<h3>開催条件</h3><ul class="event-requirements">'+check.requirements.map(r=>'<li class="'+(r.met?'positive':'negative')+'">'+(r.met?'✓ 満たしています：':'未達：')+esc(r.name)+'</li>').join('')+'</ul>':'<p class="hint">この企画に必須の設備はありません。</p>';
dialog(content(p.name,`${s.project?'<div class="notice">'+(reserved?'開催決定済み・開催費は支払い済みです。':'今月は「'+esc(C.projects[s.project].name)+'」を開催予定です。')+'</div>':''}<p>期間：${E.date(s)}の1か月。開催費 ${money(cost)}。</p><p>${p.once?"この街で一度のみ。翌年も回数は戻りません。":"年"+P.projectQuota(s,id).limit+"回まで · 今年あと"+P.projectQuota(s,id).remaining+"回。翌年1月に回数がリセットされます。"}</p>${p.description?(id==='anniversary'?`<div class="notice warning" role="note"><b>⚠️ ${esc(p.description)}</b></div>`:`<div class="notice">${esc(p.description)}</div>`):""}${requirements}${C.showMerchandise[id]?'<p>限定商品・臨時販売は当月のみ。中心店は客単価＋'+Math.round((C.showMerchandise[id].ticket-1)*100)+'％・受入能力＋'+Math.round((C.showMerchandise[id].capacity-1)*100)+'％。関連店は客単価＋8％・受入能力＋12％。中心店：'+C.showMerchandise[id].main.map(t=>esc(E.F(t).name)).join('・')+'。対象店が少ない場合や同じ企画の連月開催では効果が弱まります。仕入れ・モールン屋の使用料20％は通常どおりです。</p>':''}<p>主に恩恵を受けるお店：${p.types.filter(t=>(!E.F(t).unlockMascot||E.mascotActive(s))&&(!E.F(t).unlockMorun||E.morunKnown(s))).map(t=>E.F(t).name).join('・')}</p><p>中心となる客層：${p.target.map((n,i)=>n>=1.2?C.segments[i]:null).filter(Boolean).join('・')||'幅広い層'}。他の層も来店します。</p>${check.ok?`<dl class="detail-list"><dt>来街人数の増加見込</dt><dd>+${number(after.total-f.total)}人</dd><dt>追加売上の見込</dt><dd>${signed(after.sales-f.sales)}</dd><dt>開催費込みの企画収支見込</dt><dd>${colored(net)}</dd></dl>`:'<div class="notice warning">未達の条件を整えると開催できます。</div>'}<p class="hint">開催を決定した企画に必要な設備は、今月の開催が終わるまで撤去・改装できません。</p>`,`<div class="actions">${canReserve?action('費用を払って開催を決定','yes','primary'):s.project?'<button class="primary" disabled>今月の企画は決定済み</button>':'<button class="primary" disabled>条件を満たすと開催できます</button>'}${action(s.project?'閉じる':'見送る','no')}</div>`),{yes:()=>run(()=>P.plan(s,id)),no:closeDialog});
}
function postgameExpansionGift(){return `<section class="clear-gift"><small>最上評価限定 · 追加2段階の拡張解放</small><h3>追加区画の開放</h3><p>通常の24×24マスから、さらに2段階広げられるようになりました。</p><dl class="detail-list land-expansion-list"><dt>追加第1段階 · 26×26マス</dt><dd>${money(C.postgameExpansion.costs[0])} ／ ＋100マス</dd><dt>追加第2段階 · 28×28マス</dt><dd>${money(C.postgameExpansion.costs[1])} ／ さらに＋108マス</dd></dl><p>「隣接区画を解放」から、費用を払って順に広げます。未完了の通常拡張があれば、先に24×24マスまで進めてください。クリア時の最上評価で利用でき、追加の目標達成数は不要です。</p><p>最大で計208マスが増えます。既存の建物・道路の位置はそのままで、新しい土地への道路は自分で延ばします。</p></section>`;}
function postgameSceneryGift(){return '<section class="clear-gift"><small>最上評価限定 · 景観施設の建設解放</small><h3>城下町の景観セット</h3>'+'<img class="clear-gift-art" src="assets/castle-town-reward-v2.webp" alt="瓦屋根の白壁・石垣・松・飛び石と朱色の東屋で彩った和風の景観" width="1100" height="733" loading="lazy" decoding="async"><dl class="detail-list">'+['castleWall','castleStone','castlePine','castleRoad','castleAzumaya','castleLantern','castleKoiPond'].map(id=>{const f=E.F(id);return '<dt>'+esc(f.name)+'</dt><dd>建設費 '+money(f.cost)+' ／ 月維持 '+money(f.fixed)+'</dd>';}).join('')+'</dl><p>「道と公共施設」から配置できます。白壁・石垣・松・朱色の東屋・石灯籠・鯉のいる池は道路接続不要の景観施設で、集客・売上への効果はありません。白壁同士・石垣同士は隣接すると直線・角・分岐でつながります。飛び石の小道は隣の道路に合わせて石が並び、通常の道路と同じように接続・通行できます。</p>'+[['castleLantern','石灯籠','reward-stone-lantern.webp'],['castleKoiPond','鯉のいる池','reward-koi-pond.webp']].map(([id,title,art])=>{const f=E.F(id);return `<div class="scenery-item"><h4>${title}</h4><img class="clear-gift-art" src="assets/${art}" alt="${title}のゲーム内グラフィック" width="800" height="520" loading="lazy" decoding="async"><p>${esc(f.effect)}</p><p>面積${f.w}×${f.h}マス ／ 建設費${money(f.cost)} ／ 月維持費${money(f.fixed)} ／ 即時完成</p><p>「道と公共施設」から選んで配置できます。</p></div>`;}).join('')+'</section>'; }
function postgameGiftCards(){
 const rewards=E.postgameRewards(s);if(!rewards.basic)return '';
 const gift=(label,title,body)=>`<section class="clear-gift"><small>${label}</small><h3>${title}</h3>${body}</section>`;
 const other=E.availableTitles(s).filter(id=>id!=='reborn');
 let html=gift('称号 · 本編クリア時に授与済み','称号「商店街の再建者」',`<p>${esc(C.titles.reborn.effect)} 売上などへの数値補正はありません。</p><p>「目標・図鑑」の称号一覧で確認できます。効果のある称号は最大3個まで有効にできます。</p>${other.length?'<details><summary>この街で獲得・持越ししたほかの称号</summary>'+other.map(id=>'<p><b>'+esc(C.titles[id].name)+'</b><br>'+esc(C.titles[id].effect)+'</p>').join('')+'</details>':''}`);
 html+=gift('撮影機能 · 利用解放','街の記念撮影', '<p>育てた商店街を画像として保存できます。春夏秋冬と昼・夕方を選べます。写真の設定で経営中の季節や年月は変わりません。</p><p>画面の「記念撮影」から使えます。</p>');
 html+=gift('入口 · 無料で選択可能','クリア記念の入口', '<p>こつまるとモールンが迎える、クリア記念の入口です。整備費・維持費は0円。来客・売上への効果は普通の入口と同じです。</p><p>「入口」から選んで変更してください。現在の入口はそのまま残しています。入口変更は月1回までです。</p>');
 if(rewards.great){
 html+=postgameExpansionGift();
 const c=C.facilities.kotsumaruCastle;
 html+=gift('最上評価限定 · 建設解放','天守こつまる城', `<img class="clear-gift-art" src="assets/castle-concept.webp" alt="大きなこつまるが天守に座る、堀と石垣に囲まれた天守こつまる城" width="1100" height="880" loading="lazy" decoding="async"><p>6×6マスの記念建築を建てられるようになりました。建設費${money(c.cost)}・工期${c.months}か月・月維持費${money(c.fixed)}。城は1つまでで、完成後は四辺のどこかを道路につなぎます。</p><p>「道と公共施設」から建設できます。</p><ul><li>殿様のお散歩：晴天・穏やかな月に抽選。開催月は全客層の満足度＋2。姿を見るには、城門前の道路接続も必要です。</li><li>歴史展示：クリア時の評価や称号、街の歩みを振り返れます。</li><li>城下町まつり：年1回・開催費30万円。当月の全客層満足度＋5。台風・浸水の月は開催できません。</li><li>天守の演出：元の絵柄のこつまるが腕を振って街を迎えます。低動作設定と記念撮影では静止します。</li><li>街からの贈り物：完成・道路接続後、住民から飾りが届きます。最大6か所に飾られ、満杯後は順に入れ替わります。</li></ul><p>歴史展示とまつりは、建てた城を選んで利用できます。</p>`);
 html+=postgameSceneryGift();
 }
 html+=gift('周回 · 本編クリア時に獲得済み','次の街への称号持越し枠', `<p>この街のクリアによって、次の周回で選べる称号の枠が1個増えています。現在は最大${L.slots(meta)}個。獲得済みの称号から選んで、次の街の開始時から利用できます。</p><p>新しい街を始める画面で選択します。同じ称号の効果は二重になりません。</p>`);
 html+=gift('記録 · いつでも振り返れます','クリア評価の保存', '<p>クリア時の点数・評価クラス・成績を記録しています。クリア後の経営で評価は上書きされません。</p><p>「クリア時の評価」から、獲得した特典と説明も再確認できます。</p>');
 return '<div class="clear-gifts">'+html+'</div>';
}
function postgameGiftNotice(){
 const rewards=E.postgameRewards(s),extraLand=Boolean(s.postgameGiftsReceived&&rewards.great&&!s.postgameExpansionNotified),extraGarden=Boolean(s.postgameGiftsReceived&&rewards.great&&!s.postgameGardenNotified),extraOnly=extraLand||extraGarden;
 if(!rewards.basic||s.postgameGiftsReceived&&!extraOnly||s.status!=='playing')return false;
 const dismiss=()=>{s.postgameGiftsReceived=true;if(rewards.great){s.postgameExpansionNotified=true;s.postgameGardenNotified=true;}save();render();$('dialog').close();modalCallbacks={};};
 const body=extraOnly?'<p>最上評価のクリア特典に、新しい特典が加わりました。</p>'+(extraLand?postgameExpansionGift():'')+(extraGarden?postgameSceneryGift():''):`<p class="eyebrow">11年目1月からのクリア特典</p><p>商店街の再生、おめでとうございます！クリア評価「${esc(C.endings[s.ending.grade].name)}」に応じた特典をご用意しました。</p><p>獲得した特典を、それぞれご紹介します。解放した建築物は、好きな場所に費用を払って建てられます。</p>${postgameGiftCards()}`;
 dialog(content(extraOnly?'追加クリア特典をお届けします':'クリア特典をお届けします',body, '<div class="actions">'+action('特典を受け取って街へ','rewardDismiss','primary')+'</div>'),{rewardDismiss:dismiss});return true;
}

function postgameReview(){const r=s.ending;if(s.month<120||s.storyCompleteAt===undefined||s.status==='bankrupt'||!r)return;dialog(content('クリア時の評価',`<h3>${C.endings[r.grade].name}</h3><p>クリア年月：${E.date({month:Math.max(0,(r.clearMonth||s.storyCompleteAt)-1)})}／評価 ${number(r.score)}点</p><p>参考：クリア時の直近12か月の利益 ${money(r.annual)}／平均来街 ${number(r.avgVisitors)}人</p><dl class="detail-list">${endingScoreDetails(r)}</dl>${endingCriteria(r)}<h2>獲得したクリア特典</h2>${postgameGiftCards()}`,'<div class="actions">'+action('閉じる','close','primary')+'</div>'),{close:closeDialog});}

let photoSeason='current',photoTime='day',photoData='';
function photoMode(){if(!E.postgameRewards(s).basic)return;const copy=E.clone(s),months={春:3,夏:6,秋:9,冬:0};if(photoSeason!=='current'){copy.month=Math.floor(s.month/12)*12+months[photoSeason];copy.events.weather={month:copy.month,type:'clear'};copy.events.active=null;if(copy.communitySupport)for(const item of copy.communitySupport.items){item.receivedMonth+=copy.month-s.month;if(item.expiresMonth!==null)item.expiresMonth+=copy.month-s.month;}if(copy.castle){if(copy.castle.walkMonth===s.month)copy.castle.walkMonth=copy.month;if(copy.castle.festivalMonth===s.month)copy.castle.festivalMonth=copy.month;}}const previous={motion:town.motion,turn:town.turn,ghost:town.ghost};try{town.motion=false;town.photograph=true;town.set(copy);town.draw(0);const canvas=document.createElement('canvas');canvas.width=1100;canvas.height=760;const c=canvas.getContext('2d');c.drawImage(town.canvas,0,0);if(photoTime==='evening'){c.fillStyle='#c97c482b';c.fillRect(0,0,1100,760);const glow=c.createLinearGradient(0,0,0,760);glow.addColorStop(0,'#403b622b');glow.addColorStop(1,'#f5bd5520');c.fillStyle=glow;c.fillRect(0,0,1100,760);}photoData=canvas.toDataURL('image/png');}finally{town.photograph=false;town.motion=previous.motion;town.set(s,selected,placement);town.turn=previous.turn;town.ghost=previous.ghost;town.draw(0);}dialog(content('街の記念撮影','<img class="town-photo" src="'+photoData+'" alt="商店街の記念写真"><p>季節・時間帯は写真だけに反映します。</p><div class="photo-controls">'+['current','春','夏','秋','冬'].map(id=>action((id==='current'?'現在の季節':id)+(photoSeason===id?' ✓':''),'season'+id)).join('')+'</div><div class="photo-controls">'+['day','evening'].map(id=>action((id==='day'?'昼':'夕方')+(photoTime===id?' ✓':''),'time'+id)).join('')+'</div>','<div class="actions">'+action('画像を保存','download','primary')+action('閉じる','close')+'</div>'),{...Object.fromEntries(['current','春','夏','秋','冬'].map(id=>['season'+id,()=>{photoSeason=id;photoMode();}])),...Object.fromEntries(['day','evening'].map(id=>['time'+id,()=>{photoTime=id;photoMode();}])),download:()=>{const a=document.createElement('a');a.href=photoData;a.download='kotsukotsu-demo-town-'+(s.month+1)+'.png';a.click();},close:closeDialog});}
function loan(){const balance=s.debts.reduce((a,d)=>a+d.balance,0),canRepay=E.canAct(s)&&E.availableCash(s)>=balance;dialog(content('借入・返済',`<p>借入残高の上限 ${money(C.loanCap)}。現在 ${money(balance)}。</p><p>月利0.5%、36回の元金均等返済。翌月の決算から元金と利息を払います。</p><label>借入額（万円） <input id="loanAmount" type="number" min="10" max="${Math.floor((C.loanCap-balance)/10000)}" step="10" value="100"></label><p class="hint">100万円なら、初月の返済は元金約2.8万円＋利息0.5万円です。</p>${balance>0?'<h3>一括繰上返済</h3><p>残元金 '+money(balance)+'をまとめて返済できます。手数料はなく、返済後の利息はかかりません。</p>'+(!canRepay?'<p class="hint">納税資金を除いた使用可能な資金が足りない場合や、資金ショート中は返済できません。</p>':''):''}`,`<div class="actions">${action('この条件で借りる','yes','primary')}${balance>0?(canRepay?action('残りを一括返済する','repay'):'<button disabled>残りを一括返済する</button>'):''}${action('閉じる','no')}</div>`),{yes:()=>run(()=>E.borrow(s,Number($('loanAmount').value)*10000)),repay:confirmRepay,no:closeDialog});}
function confirmRepay(){const balance=s.debts.reduce((n,d)=>n+d.balance,0);dialog(content('借入を一括返済しますか？',`<p>残元金 ${money(balance)}を返済します。</p><p>返済後の使用可能な資金：${money(E.availableCash(s)-balance)}。納税用に確保した資金は使いません。</p>`,`<div class="actions">${action('一括返済する','yes','primary')}${action('戻る','no')}</div>`),{yes:()=>run(()=>E.repayAll(s)),no:loan});}

function rescue(){if(s.storyFailed||s.status==='bankrupt'){campaignFailure();return;}const short=s.cash<0;dialog(content(s.status==='bankrupt'?'再生計画断念':short?'資金ショートを立て直す':'資金対策',`<div class="rescue"><b>運営資金 ${money(s.cash)}</b><p>${short?'資金を0円以上にするまで、次の月には進めません。':'月間赤字だけではゲームオーバーになりません。'}</p>${s.last?'<p>前月の利益 '+signed(s.last.profit)+'／投資 '+money(s.last.spent.construction)+'／元金返済 '+money(s.last.repayment)+'</p>':''}</div><p>店舗を売却する、返済義務のある借入をする、または一度限りの再生支援金を使えます。再生支援金は資金ショート時に、この街で一度だけ申請できます。</p><div class="actions">${action('店舗を売却','sell')}${action('借入・返済','loan')}</div><div class="actions">${!s.grantUsed?(s.status==='rescue'&&short?action('再生支援金250万円','grant','primary'):'<span class="hint">再生支援金250万円：資金ショート時のみ申請可能</span>'):'<span class="hint">再生支援金は利用済み</span>'}${s.lastDisaster&&!s.lastDisaster.aidUsed?action('災害復旧支援35万円','aid'):''}</div>${short?`<div class="actions">${action('再生計画を断念する','abandon','danger')}</div>`:''}${s.status==='bankrupt'?`<p>資金不足の主因を収支表で見直し、直前の月初から判断をやり直せます。</p><div class="actions">${action('直前の月初から再挑戦','retry','primary')}</div>`:''}`),{sell:buildingList,loan,grant:()=>confirmGrant(),aid:()=>run(()=>V.aid(s)),abandon:()=>dialog(content('再生計画を断念しますか？','<p>現在の計画を終了します。直前の月初から再挑戦できます。</p>',`<div class="actions">${action('断念する','yes','danger')}${action('戻る','no')}</div>`),{yes:()=>run(()=>E.abandon(s),()=>rescue()),no:rescue}),retry:()=>{const r=E.retryMonth(s);if(r.error)toast(r.error);else{s=r.state;save();render();closeDialog();toast('直前の月初へ戻りました。');}}});}
function confirmGrant(){dialog(content('再生支援金を受け取る',`<p>資金ショート時に250万円を一度だけ受け取れます。支援利用は最終評価に残りますが、クリアは可能です。</p>`,`<div class="actions">${action('申請する','yes','primary')}${action('戻る','no')}</div>`),{yes:()=>run(()=>E.grant(s)),no:rescue});}
function buildingList(){dialog(content('店舗・施設一覧',`<p>建物名から詳細へ。売却や改装もここから行えます。</p><div class="table-scroll"><table class="data-table"><thead><tr><th>施設</th><th>場所</th><th>状態</th></tr></thead><tbody>${orderedBuildings().map(b=>`<tr><td><button data-do="b${b.id}">${E.F(b.type).name}</button><small class="building-list-level">${E.F(b.type).shop?`改装 Lv.${b.level}/3${b.pendingLevel?` → Lv.${b.pendingLevel}（改装中）`:""}`:"改装対象外"}</small></td><td>${b.x+1},${b.y+1}</td><td>${b.build?'工事'+b.build+'月':b.closed?'休業'+b.closed+'月':E.network(s).connected(b)?'接続':'未接続'}</td></tr>`).join('')}</tbody></table></div>`),Object.fromEntries(s.buildings.map(b=>['b'+b.id,()=>{const scroll=$('dialog').scrollTop;detail(b.id,()=>{buildingList();$('dialog').scrollTop=scroll;});}])));}
function rival(){const a=s.events.active;if(a?.kind!=='rival'){toast('今月は対抗企画がありません。');return;}dialog(content(C.rivals[a.type].name,`<p>${esc(V.rivalAnnouncement(a.type))}</p><p>あと${a.left||1}か月、来店率と買上額が下がります。対抗策は当月のみ有効です。</p>${Object.entries(C.responses).map(([id,r])=>`<button class="spec-option" data-do="r${id}" ${s.responseChosen?'disabled':''}><b>${r.name} · ${money(r.cost)}</b><small>${r.effect}</small></button>`).join('')}<p>現在：${C.responses[s.response].name}${s.responseChosen?'（決定済み）':'。選ばずに資金を温存することもできます。'}</p>`),Object.fromEntries(Object.keys(C.responses).map(id=>['r'+id,()=>run(()=>V.respond(s,id))])));}
function prepare(){if(!V.canPrepare(s)){toast('今月は大雨・浸水の対策対象ではありません。');return;}dialog(content('大雨・浸水への臨時防災対策',`<p>費用18万円。予告された大雨・浸水1回の被災確率・損失・休業期間を軽減します。防災設備と組み合わせると効果が高まります。</p><p>${s.prepared?'対策は実施済みです。':'必要な対策を選びましょう。'}</p>`,`<div class="actions">${action('18万円で実施する','yes','primary')}</div>`),{yes:()=>run(()=>V.prepare(s))});}
function eventBrief(automatic=false){const alerts=V.alerts(s),good=V.goodNews(s).filter(n=>!automatic||n.announce);const tax=E.taxNotice(s),stories=[...(tax?[tax]:[]),...good];if(!alerts.length&&!stories.length)return false;let added=false;for(const n of [...stories,...alerts.filter(n=>n.art)])if(n.art&&!s.seenArt.includes(n.art)){s.seenArt.push(n.art);added=true;}if(added){recordMeta();save();if(tab==='goals')renderTools();}dialog(`<div class="dialog-content"><h2>街からのお知らせ</h2><p>${tax?'納税のお知らせ 1件 ／ ':''}うれしい知らせ ${good.length}件${alerts.length?' ／ 注意・被害 '+alerts.length+'件':''}</p>${alerts.map(a=>`<section>${a.art?`<img class="event-art" src="assets/event-${a.art}.webp" alt="${esc(a.title)}">`:''}<div class="notice warning"><b>${esc(a.title)}</b><p>${esc(a.text)}</p></div></section>`).join('')}${stories.map(n=>`<section class="good-event">${n.itemId?'<div class="item-acquired-art">'+supportIcon(n.itemId)+'</div>':n.art?`<img class="event-art good-event-art" src="assets/event-${n.art}.webp" alt="${esc(n.title)}">`:n.kind==='sunny'?`<div class="sunny-event-badge">${KWeatherBadge.badge('sunny').html}</div>`:n.kind==='mascot'?`<div class="sunny-event-badge">${KMascot.icon()}<span>商店街マスコット・こつまる</span></div>`:''}<div class="notice good-news"><b>${esc(n.title)}</b><p>${esc(n.text)}</p></div></section>`).join('')}<div class="actions">${V.canPrepare(s)&&!s.prepared?action('大雨・浸水への対策を検討','prepare'):''}${s.events.active?.kind==='rival'?action('競争への対応を検討','rival'):''}${V.canAid(s)?action('復旧支援を申請','aid'):''}${stories.some(n=>n.itemId)?action('記念品・装備','souvenirs'):''}${stories.some(n=>n.kind==='communitySupport')?action('地域応援の支援先を選ぶ','communitySupport'):''}${action('確認して街へ','close','primary')}</div></div>`,{close:closeDialog,souvenirs:()=>communitySupportDialog('items'),communitySupport:communitySupportDialog,prepare,rival,aid:()=>run(()=>V.aid(s))});return true;}
function expand(){const showExtra=Boolean(s.storyVersion===2&&s.storyCompleteAt!==undefined&&!s.storyFailed&&!s.retrySupport&&s.ending?.grade==='great'),info=E.expansionInfo(s),normal=C.balance.expansionCosts.map((cost,i)=>{const target=C.baseSize+(i+1)*2;return `<dt>第${i+1}拡張 · ${target}×${target}${s.size>=target?' ✓':''}</dt><dd>${money(cost)}<br>目標${C.balance.expansionGoals[i]}件、または${E.date({month:C.balance.expansionMonths[i]})}</dd>`;}).join(''),extra=C.postgameExpansion.costs.map((cost,i)=>{const target=C.maxSize+(i+1)*2;return `<dt>追加第${i+1}段階 · ${target}×${target}${s.size>=target?' ✓':''}</dt><dd>${money(cost)}<br>${info.postgameUnlocked?'特典解放済み':'最上評価クリア後・11年目1月から'}</dd>`;}).join('');
 dialog(content('隣接区画を解放',`<p>現在 ${s.size}×${s.size}マス。${info.maxed?info.locked?'通常の区画はすべて解放しました。'+(showExtra?'追加区画は最上評価のクリア特典です。':''):'すべての区画を解放しました。':'右と奥へ '+info.target+'×'+info.target+'マスに広げます。'}</p>${!info.maxed?'<p><b>今回の費用 '+money(info.cost)+'</b></p>':''}<dl class="detail-list land-expansion-list">${normal}</dl>${showExtra?`<h3>クリア特典 · 追加2段階</h3><dl class="detail-list land-expansion-list">${extra}</dl><p>追加区画は24×24までの通常拡張を終えてから、26×26、28×28の順に解放します。</p>`:''}<p>既存の建物の場所は変わりません。道路の延長も忘れずに。施設を増やすと維持費も増えます。</p>`,`<div class="actions">${!info.maxed?action('費用を払って解放','yes','primary'):''}${action('閉じる','close')}</div>`),{yes:()=>run(()=>E.expand(s)),close:closeDialog});}

const ART={security:['治安悪化！','夕暮れの通りに、不安の声が広がりました。店主と交番の見回りが、いつもの安心を取り戻すために動き始めます。'],quiet:['ガラガラ','店先には商品が並ぶものの、通りを歩く人はまばら。お客さんを迎える店主たちが、次の賑わいを待っています。'],congestion:['大混雑','人気が集まる一方、店先には長い列ができ、休む場所を探すお客さんも。街の受け入れ態勢を整える時です。'],'morun-break':['モールンブレイク↗︎','写真にグッズに、話題の中心はモールン。大型商業施設には、お目当ての人たちが続々と集まっています。'],morun:['モールンだよ！','大型商業施設から、狐のマスコット「モールン」がやってきました。華やかなごあいさつに、こつまるもびっくり。'],'shrine-gift':['神様からの贈り物','大切に守ってきた神社で、不思議な宝箱が見つかりました。神様の心遣いを、これからの街づくりへ。'],donation:['街から、地域へのおすそわけ。','11月は地域応援月間。支援は任意で、記念品を装備すると12か月間の受入能力アップと街の飾りを楽しめます。'],'tenant-diner':['人気の定食チェーンからの出店要請','空き地の使い方と場所代、近隣店との競合を考える、新しい街づくりの機会です。'],'tenant-sweets':['話題のスイーツ専門店からの出店要請','空き地の使い方と場所代、近隣店との競合を考える、新しい街づくりの機会です。'],'tenant-tea':['老舗のお茶・和菓子店からの出店要請','空き地の使い方と場所代、近隣店との競合を考える、新しい街づくりの機会です。'],'tenant-character':['キャラクター雑貨店からの出店要請','空き地の使い方と場所代、近隣店との競合を考える、新しい街づくりの機会です。'],'mascot-break':['こつまるブレイク↗︎','こつまるの写真や口コミが話題になり、商店街に会いに来るお客さんが増えました。商店街全体の来店率と、こつまる屋の商品需要に期間限定の追い風が生まれた日の記録です。'],tax:['毎年5月は、納税の月。','前年の年間利益がプラスなら15%を納税。1年目の利益は再建支援により免税です。'],opening:['小さな一歩から、もう一度。','大型商業施設ができてから、通りの灯りが少しずつ減りました。古いパン屋、喫茶店、花屋とともに、10年目12月までに商店街の再生を目指します。'],fair:['「また来たい」が、聞こえた日。','初めて開催費を上回る成果が出ました。企画だけでなく、お店の特色や受入能力が支えた一日です。'],boom:['この街に、小さなブーム。','いま、パンや喫茶店巡りが話題です。期間限定の追い風を、固定客につなげてみましょう。'],summer:['提灯の下で、街が笑う。','夏祭りが実を結びました。いつもの通りで、人と人が出会います。'],disaster:['雨の向こうに、いつもの街を。','災害の被害を確認しましょう。修理や復旧支援、自然復旧を組み合わせて営業を取り戻せます。'],recovery:['おかえり、いつもの灯り。','休業していたお店が再び動き始めました。対策の経験も、この街の力になります。'],'ending-good':['また来たくなる、わたしたちの街。','世代をこえて訪れる人が増え、商店街ならではの時間が育ちました。'],'ending-mid':['小さな灯りが、街の力に。','経営の土台を取り戻しました。次はまだ出会えていない人たちに、この街の魅力を届けましょう。'],'ending-low':['再生途上。物語は、まだ続く。','10年の区切りを迎えました。これは破産ではありません。育てた街で、これからも経営を続けられます。']};
Object.assign(ART,{
 'story-0':['序章「もう一度、店に灯りを」','新しくなった店先に、お客さんが戻ってきました。ひとつの灯りから、商店街の再建が動き始めます。'],
 'story-1':['第1章「シャッターの向こうへ」','閉ざされていた店先に、商品と笑顔が戻りました。シャッターの向こうから、今日も「いらっしゃいませ」が聞こえます。'],
 'story-2':['第2章「この街らしさを探して」','お店が力を合わせて生まれた、この街ならではの楽しみ。「また来たい」という声が、次の自信につながりました。'],
 'story-3':['第3章「また来たくなる通り」','ひと休みできる場所と、いつもの見守り。買い物をする人にも、迎える人にも、心地よい通りが育ちました。'],
 'story-4':['第4章「この街の顔になって」','街のみんなで育てた想いが、新しい顔になりました。お披露目を待つ人たちの期待が、通りいっぱいに広がります。'],
 'story-5':['第5章「ライバルのいる街」','華やかな大型商業施設にも、この通りにしかない楽しさで応えます。舞台に集まった笑顔が、商店街の底力を教えてくれました。'],
 'story-6':['第6章「次の一歩に賭ける」','思い切って踏み出した一歩が、新しい街の魅力になりました。日々の営みを守りながら育てた事業は、これからの支えになります。'],
 'story-7':['第7章「この街が目的地になる」','街の象徴を見上げ、写真を撮る人、店を巡る人。「この街に行きたい」と訪れる人たちが、通りの新しい日常になりました。'],
 'story-8':['最終章「こつこつ、その先へ」','ひとつの灯りから始まった歩みは、街いっぱいの笑顔になりました。支えてくれたみなさんと、商店街の新しい未来を祝います。'],
 'future-town':['未来商店街','百年の間に、店も、街の姿も、訪れる人たちも変わりました。それでも、この通りで誰かを迎える灯りは、途切れることなく受け継がれています。あなたが育てた商店街は、次の百年へ歩み始めます。'],
 'story-failure':['街の灯が消える日','再び灯りをともすという願いは、届きませんでした。再建計画は終わり、通りは静かに最後の営業を終えます。'],
 'mascot-help':['こつまる、商店街のお手伝い','いつものお店の前で、こつまるが元気に呼び込み。立ち寄ったお客さんとお店の人に、笑顔が広がりました。'],
 'mascot-letter':['こつまるに届いたお手紙','小さな手で描かれた似顔絵と、応援のお手紙。こつまるにとって、商店街の宝物がまたひとつ増えました。'],
 'mascot-duet':['こつまるとモールン、まさかの共演！','商店街のこつまると、大型商業施設のモールン。二人が並んで手を振ると、通りいっぱいに拍手が広がりました。']
});
for(const [grade,info] of Object.entries(C.endings))ART['ending-'+grade]=[info.title,info.text];
for(const p of Object.values(C.projects))if(p.art)ART[p.art]=[p.name,p.artText];
function artInfo(a){const v=ART[a]||ART.opening;return {title:v[0],text:v[1]};}
function introTitle(scene=false){return `<div class="intro-title">${scene?'<img class="intro-scene" src="assets/event-opening.webp" alt="" aria-hidden="true">':''}<img class="intro-title-logo" src="assets/title-logo.webp" width="768" height="512" alt="こつこつ商店街" decoding="async" draggable="false"></div>`;}
function titleModes(){return '<div class="actions title-actions">'+action('最初から始める','mode-standard')+'</div>'+(L.retrySupportAvailable(meta)?'<div class="notice">'+action(C.retrySupport.name,'mode-retrySupport')+'<p>'+C.retrySupport.description+'</p></div>':'');}
function chooseStartMode(mode){
 if(s.retrySupport){confirmNew([],mode);return;}
 if(mode==='century'&&!L.centuryAvailable(meta))return;
 if(!s.pendingStart||s.month!==0||s.status!=='playing'){confirmNew([],mode);return;}
 s.mode=mode;finishPendingStart();render();closeDialog();
 globalThis.scrollTo({top:0,left:0,behavior:'instant'});
}
function titleModeActions(){return {fresh:confirmFresh,profiles:profileMenu,'mode-standard':()=>chooseStartMode('standard'),'mode-retrySupport':()=>confirmNew([],'retrySupport'),'mode-century':()=>chooseStartMode('century')};}
function titleScreen(resumable=true){
 recordMeta();
 dialog(introTitle()+content('こつこつ商店街',`
 ${resumable?'<div class="resume-save"><small>保存している街 · '+E.modeInfo(s).name+'</small><strong>'+E.date(s)+'</strong><span>運営資金 '+money(s.cash)+'</span></div><div class="actions title-actions">'+action('続きから遊ぶ','continue','primary')+'</div>':''}
 ${titleModes()}
 <div class="actions">${action('引き継がずに新しく始める','fresh')}${action('保存した街から遊ぶ','profiles')}</div>
 `,introSoundControl()),{
 continue:()=>{musicReady=true;render();closeDialog();if(modalCallbacks.rewardDismiss)return;if(s.storyVersion===2&&(s.storyEvents.length||s.storyFailed)){if(s.storyFailed&&!s.storyEvents.length)campaignFailure();return;}if(s.status==='rescue'||s.status==='bankrupt')rescue();else if(s.status==='ending')ending();else if(E.taxNotice(s))eventBrief(true);},
 ...titleModeActions()
 });
 $('dialog').scrollTop=0;
}
function showArt(a,archive=false){const info=artInfo(a),showModes=a==='opening'&&!archive&&L.centuryAvailable(meta);if(!archive){if(!s.seenArt.includes(a))s.seenArt.push(a);recordMeta();save();}dialog(`${a==='opening'?introTitle(true):(a.startsWith('story-')?campaignIllustration(a):`<img class="event-art" src="assets/event-${a}.webp" alt="${info.title}">`)}<div class="dialog-content">${showModes?titleModes():''}${a==='opening'&&s.mode==='century'?'<p class="eyebrow">100年商店街 · 100年の経営に挑戦</p>':''}<h2>${info.title}</h2><p>${s.mode==='century'&&a==='opening'?info.text.replace('10年間','100年間'):info.text}</p>${a==='opening'?introSoundControl()+'<p>お店をタップして改装・品ぞろえを選び、空き区画には仮の建物をドラッグして配置。道路を入口につなげましょう。「翌月へ」を押した時だけ経営時間が進みます。</p>':''}<div class="actions">${action(a==='opening'?'この街を育てる':'街へ戻る','close','primary')}</div></div>`,{close:closeDialog,...(showModes?titleModeActions():{})});$('dialog').scrollTop=0;}
function endingCriteria(result){if(result&&result.evaluationVersion!==C.evaluationRules.version)return '<p class="hint">この記録は旧基準です。過去の決算記録が不足しているため、新しい配点で再計算せず、保存済みの合計点・クラスを維持しています。</p>';const grades=Object.keys(C.endings),r=C.evaluationRules;return `<details class="ending-criteria"><summary>5段階の判定基準</summary><p>累計利益・来街人数・満足度・客層の点数と減点を合計し、早期クリアボーナスを加えて評価クラスを決めます。</p><dl>${grades.map((grade,i)=>'<dt>'+C.endings[grade].name+'</dt><dd>'+number(C.endingRules[grade])+'点'+(i?'〜'+number(C.endingRules[grades[i-1]]-1)+'点':'以上')+'</dd>').join('')}</dl><p>累計利益：税金を費用として引いた毎月の利益の合計÷${number(r.profitYenPerPoint)}。赤字も通算します。初期資金・借入・支援金・章の報酬は含みません。建設や改装に再投資しても、稼いだ実績は残ります。</p><p>平均来街人数×${r.visitorPoints}。4客層の平均満足度×${r.satisfactionPoints}。客層ごとの平均来街率が上限の25％以上なら各${r.breadthPoints}点。来街人数・満足度・客層は直近12か月で評価します。</p><p>空き店舗率1％につき${r.vacancyPenalty}点、借入残高${number(r.debtYenPerPoint)}円につき1点、再生支援金を利用した場合${r.grantPenalty}点を減点。各項目を四捨五入して合計し、経営成績点は最低0点です。</p><p>早期クリアボーナス：15年目12月（180か月）より1か月早いごとに${C.earlyClearRules.pointsPerMonth}点。直近12か月の利益は参考表示で、累計利益と重複して加点しません。クリア時の合計点とクラスを記録します。</p></details>`;}
function endingScoreDetails(r){
 if(r.evaluationVersion!==C.evaluationRules.version)return `<dt>保存済みの経営成績点（旧基準）</dt><dd>${number(r.baseScore??r.score)}点</dd><dt>早期クリアボーナス（旧基準）</dt><dd>＋${number(r.earlyBonus??0)}点</dd><dt>評価基準</dt><dd>過去の決算記録が不足しているため、クリア時の旧評価を保持しています。</dd>`;
 const names={profit:'累計利益の点数',visitors:'来街人数の点数',satisfaction:'満足度の点数',breadth:'客層の広がりの点数',vacancy:'空き店舗の減点',debt:'借入残高の減点',grant:'再生支援金の減点'};
 return `${r.retrySupport?'<dt>再挑戦支援スタート</dt><dd>初期資金の支援を利用したため、最高ランクは獲得できません。</dd>':''}<dt>${r.cumulativeComplete?'開始からの累計利益':'記録が残る期間の利益'}</dt><dd>${money(r.cumulativeProfit)}</dd>${!r.cumulativeComplete?'<dt>集計期間</dt><dd>'+E.date({month:r.cumulativeSince})+'以降（それ以前の決算記録なし）</dd>':''}${Object.entries(names).map(([key,name])=>'<dt>'+name+'</dt><dd>'+number(r.points[key])+'点</dd>').join('')}<dt>経営成績点</dt><dd>${number(r.baseScore)}点</dd><dt>早期クリアボーナス</dt><dd>＋${number(r.earlyBonus)}点</dd>`;
}
function futureEnding(){const a='future-town';if(!s.seenArt.includes(a))s.seenArt.push(a);recordMeta();save();dialog(`<img class="event-art" src="assets/event-future-town.webp" width="1280" height="720" alt="百年先へ続く未来商店街"><div class="dialog-content future-ending"><p class="eyebrow">100年目12月 · 100周年</p><h2>未来商店街</h2><p>${artInfo(a).text}</p><p><strong>ここまでプレイしてくれてありがとう</strong></p><div class="actions">${action('街を眺める','map')}${action('タイトル画面へ','title')}${action('称号を選んで新しい街へ','newCycle','primary')}</div></div>`,{map:closeDialog,title:titleScreen,newCycle:()=>confirmNew()},{endingMusic:true});}
function ending(){if(E.futureComplete(s)){futureEnding();return;}if(s.storyVersion===2){campaignEnding();return;}const r=s.ending;if(!r)return;const a='ending-'+r.grade;if(!s.seenArt.includes(a))s.seenArt.push(a);recordMeta();save();dialog(`<img class="event-art" src="assets/event-${a}.webp" alt="最終年の商店街"><div class="dialog-content"><p class="eyebrow">${E.modeInfo(s).years}年目12月 · 最終決算</p><h2>${r.title}</h2><p>${esc(s.mode==='century'?C.endings[r.grade].text.replaceAll('十年','百年'):C.endings[r.grade].text)}</p><dl class="detail-list"><dt>直近12か月の利益合計（参考・加点なし）</dt><dd>${colored(r.annual)}</dd><dt>月間来街人数の平均</dt><dd>${number(r.avgVisitors)}人</dd><dt>広がった客層</dt><dd>${r.breadth} / 4層</dd>${r.satisfaction?'<dt>客層別の平均満足度</dt><dd>'+r.satisfaction.map((n,i)=>C.segments[i]+' '+n).join(' ／ ')+'</dd>':''}<dt>本編の章</dt><dd>${r.chapters??(s.storyDone||[]).length} / ${C.chapters.length}</dd><dt>目標達成（参考）</dt><dd>${r.goals??s.claimed.length} / ${C.goals.length}</dd><dt>空き店舗率</dt><dd>${r.vacancy}%</dd><dt>借入残高</dt><dd>${money(r.debt)}</dd><dt>再生支援金</dt><dd>${r.grantUsed?'利用あり':'利用なし'}</dd>${endingScoreDetails(r)}<dt class="total">${E.modeInfo(s).years}年評価（合計点）</dt><dd class="total">${number(r.score)}点 · ${C.endings[r.grade].name}</dd></dl>${endingCriteria(r)}<p class="hint">目標の達成数・全業種の収集は、再生達成の必須条件ではありません。</p>${L.cleared(s)?'<p>再生達成 '+meta.clears.length+'回。次は'+(meta.clears.length+1)+'周目、称号を最大'+L.slots(meta)+'個選んで持ち越せます。</p>':''}${L.centuryAvailable(meta)?'<p>「100年商店街」を、タイトル画面で選べます。</p>':''}<div class="actions">${action('育てた街を振り返る','map')}${action('タイトル画面へ','title')}${L.cleared(s)?action('称号を選んで次の周回へ','newCycle','primary'):action('次の商店街を始める','newCycle','primary')}</div></div>`,{newCycle:()=>confirmNew([],s.mode||'standard'),title:titleScreen,map:()=>{closeDialog();$('town').scrollIntoView({behavior:'smooth',block:'center'});toast(E.modeInfo(s).years+'年目終了時の街です。下のボタンから評価に戻れます。');}},{endingMusic:true});}
async function nextMonth(){if(E.mascotActive(s)){demoEnd();return;}if(s.storyFailed){campaignFailure();return;}if(profileBusy||!storageReady||advancing||savePending||placement)return;if(s.status==='rescue'||s.status==='bankrupt'){rescue();return;}if(s.status==='ending'){ending();return;}finishPendingStart();advancing=true;$('next').disabled=true;try{const r=E.advance(s);if(r.error){toast(r.error);return;}placement=null;selected=null;recordMeta();const monthSave=save();render();globalThis.scrollTo({top:0,left:0,behavior:'instant'});if(E.mascotActive(s)){demoBirth();return;}if(s.storyVersion===2&&storyNotice()){}else if(s.status==='rescue'){if(E.taxNotice(s))eventBrief(true);else rescue();}else if(s.status==='ending')ending();else if(!eventBrief(true)){const a=s.milestones.find(a=>ART[a]&&!['boom','fair','summer','recovery'].includes(a)&&!s.seenArt.includes(a));if(a)showArt(a);else toast(E.date(s)+'になりました。前月の決算を確認できます。');}await monthSave?.catch(()=>{});}finally{advancing=false;render();}}
