function confirmFresh(){if(!storageReady||profileBusy)return;if(profiles.entries.length>=KGameProfiles.maxProfiles){dialog(content('街の保存枠がいっぱいです','<p>街は５枠まで保存できます。今ある街はそのまま残っています。</p>',action('保存した街から遊ぶ','profiles')+action('戻る','back')),{profiles:profileMenu,back:saveMenu});return;}dialog(content('引き継がずに新しく始めますか？','<p>称号・図鑑・最高記録・周回数・解放状況を引き継がず、1年目1月から始めます。</p><p>今の街と記録は別枠に残ります。「保存した街から遊ぶ」から戻れます。</p><p>メインストーリー・初期資金'+money(C.initialCash)+'で開始します。</p>','<div class="actions">'+action('まっさらな街を始める','yes','primary')+action('戻る','no')+'</div>'),{yes:beginFresh,no:saveMenu});}
async function persistProfile(store,text,requireCloud=true){const result=await store.write(text).done;if(!result.ok||(store.hosted&&!result.cloud&&(requireCloud||!(result.local||result.mirror))))throw Error('保存を確認できませんでした。元の街のままです。接続や保存容量を確認してお試しください。');return result;}
