async function switchProfile(id){if(profileBusy||!storageReady||id===currentProfile)return;if(!profiles.entries.some(p=>p.id===id))return;profileBusy=true;const ready=storageReady;storageReady=false;$('next').disabled=true;dialog(content('街を開いています…','<p>今の街を保存してから、選んだ街を読み込みます。</p>'));try{recordMeta();const outgoing=await persistProfile(storage,E.serialize(s),false);if(manualSaved)await persistProfile(manualStorage,E.serialize(manualSaved),false);const keys=KGameProfiles.keys(id),automatic=new KSaveStorage(keys.auto,E.deserialize),manual=new KSaveStorage(keys.manual,E.deserialize),load=store=>new Promise(resolve=>store.load(resolve)),a=await load(automatic),m=await load(manual),target=a.state?a:m;if(!target.state)throw Error(target.error||'この街の保存を読み込めませんでした。');const next={...profiles,active:id};await persistProfile(profileStorage,JSON.stringify(next));profiles=next;installProfile(id,automatic,manual,target.state,readProfileMeta(id));manualSaved=m.state||null;profileBusy=false;save();render();closeDialog();globalThis.scrollTo({top:0,left:0,behavior:'instant'});if(s.status==='rescue'||s.status==='bankrupt')rescue();else if(s.status==='ending')ending();else if(E.taxNotice(s))eventBrief(true);if(outgoing.hosted&&!outgoing.cloud)toast('前の街はこの端末に保存しました。オンライン保存は未確認です。');}catch(e){profileBusy=false;storageReady=ready;render();dialog(content('街を開けませんでした','<p>今の街は切り替えていません。</p><p>'+esc(e.message)+'</p>',action('街の一覧に戻る','back')),{back:profileMenu});toast(e.message);}}
